INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('40f0c502-b69f-49f1-b505-b401a9409bcf', '21feff02-016d-46e2-bb9d-c27495133b1b', '51. óra: A kör', 'A kör elemei: középpont (O), sugár (r), átmérő (d), húr, körív, körző használata.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "dc229114-11f4-4736-8615-15670ecc3b8c", "text": "Hogyan viszonylik a kör átmérője (d) a sugárhoz (r)?", "type": "multiple-choice", "options": [{"id": "f5333362-f8d0-45af-9617-0bf5305703e5", "text": "d = 2 * r (az átmérő a sugár kétszerese)", "isCorrect": true}, {"id": "b4d29cca-a501-491d-bca4-70a585638f1a", "text": "d = r / 2", "isCorrect": false}, {"id": "c067a619-e216-455a-a412-8eba10264216", "text": "d = r + 5", "isCorrect": false}, {"id": "aa2728db-e33d-423a-b415-b5dff011817d", "text": "d = r * r", "isCorrect": false}], "timeLimit": 15}, {"id": "c4751acd-9fd5-4d9d-8ef5-277f52d3f22b", "text": "Ha a kör sugara r = 5 cm, mennyi az átmérője (d)? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "8664e461-940c-4b32-b157-426b74a47b11", "text": "Ha a kör átmérője d = 16 cm, mennyi a sugara (r)? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "d3f8ab9c-b011-481c-bd39-f26fbf6410c8", "text": "A körvonal pontjai a középponttól egyenlő távolságra (sugárnyira) vannak.", "type": "true-false", "options": [{"id": "f9dce187-1f13-4982-bd36-2587bceea303", "text": "Igaz", "isCorrect": true}, {"id": "1cb4be4b-1c5a-4782-9737-350dc2feee0f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5d5db47b-4dd9-4a12-94f7-459f002cdb38", "text": "Mi a kör leghosszabb húrja?", "type": "multiple-choice", "options": [{"id": "f083d364-b454-4b00-9a59-2d17b6f0515f", "text": "Az átmérő", "isCorrect": true}, {"id": "69e30299-79a4-4832-8de6-2cb7394db132", "text": "A sugár", "isCorrect": false}, {"id": "366cba30-400a-4b7d-b067-3fcdce683f5e", "text": "A körív", "isCorrect": false}, {"id": "9b9dea59-1491-4069-9b02-277846eb2f71", "text": "A körcikk", "isCorrect": false}], "timeLimit": 15}, {"id": "f0e5e71b-42a9-4d55-a511-e98e6b535757", "text": "A körző a körök rajzolására és távolságok másolására szolgáló szerkesztőeszköz.", "type": "true-false", "options": [{"id": "efee909a-36b1-47a9-9492-78a0c2d6803a", "text": "Igaz", "isCorrect": true}, {"id": "63bbe43a-6109-4a11-ad7b-b129f28d6b69", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "eb22fc1b-70e8-473f-b9ce-24ca477ca7bc", "text": "A kör belsejében lévő pontok távolsága a középponttól kisebb, mint a sugár.", "type": "true-false", "options": [{"id": "52bd7d4c-7d10-4096-a685-620994a067ee", "text": "Igaz", "isCorrect": true}, {"id": "482f5bc0-7c4e-4243-b668-d6813df86236", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('201e5ce7-28aa-40c1-add2-868f3edf0aaf', '21feff02-016d-46e2-bb9d-c27495133b1b', '52. óra: A szakasz felezőmerőlegese', 'A szakaszfelező merőleges tulajdonságai, szerkesztése körzővel és vonalzóval.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "6f23eb6e-38af-4f6e-96ee-885f80462b5c", "text": "Mi a szakaszfelező merőleges egyenes fő tulajdonsága?", "type": "multiple-choice", "options": [{"id": "c5e46cfb-8689-4889-90c2-9239ad36f522", "text": "A szakasz felezőpontján áthaladó, a szakaszra merőleges egyenes, melynek pontjai egyenlő távolságra vannak a szakasz két végpontjától", "isCorrect": true}, {"id": "25da46a1-ce3b-4257-9432-567cc859e7cc", "text": "A szakasszal párhuzamos egyenes", "isCorrect": false}, {"id": "214b06bc-affe-467b-860c-647e84dd24bc", "text": "A szakasz egyik végpontján átmenő egyenes", "isCorrect": false}, {"id": "954c57bd-23c9-4eb0-890b-df48ff18dc4b", "text": "Minden szakaszhoz 2 felezőmerőleges tartozik", "isCorrect": false}], "timeLimit": 15}, {"id": "1974f452-148a-4fbb-a61f-1e9d53a61566", "text": "Hány felezőmerőlegese van egy szakasznak a síkban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "6be218ef-0124-4334-a918-550f35ae674f", "text": "A szakaszfelező merőleges egyenes pontjai egyenlő távolságra vannak a szakasz két végpontjától.", "type": "true-false", "options": [{"id": "4f50f8cd-264b-4bb5-9d7f-45b564d0b284", "text": "Igaz", "isCorrect": true}, {"id": "98499729-f4e4-44ee-9498-5f8f6be2d62e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6f7630b2-caaa-46b7-84e9-2d95d82730c5", "text": "A szakasz felezőmerőlegesének megszerkesztéséhez a szakasz felénél nagyobb körzőnyílás szükséges.", "type": "true-false", "options": [{"id": "90738a56-5495-407e-8523-6a70df6d9d0e", "text": "Igaz", "isCorrect": true}, {"id": "c90db294-e10d-4013-9941-37b84f309d38", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0bc806c6-169c-42a3-ae7c-8a95f89f9b7e", "text": "Hány fokos szöget zár be a felezőmerőleges a szakasszal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "1aa1b6a3-01c3-4d84-9edd-8a4fe3290c65", "text": "A háromszög oldalfelező merőlegesei egy pontban metszik egymást (a körülírt kör középpontjában).", "type": "true-false", "options": [{"id": "99bf5889-9bc8-4712-80d9-76026fa302a9", "text": "Igaz", "isCorrect": true}, {"id": "befeee9c-78bd-442e-8f21-6cc0f66e0495", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "13f967a7-d78c-44f8-8e5d-9c0080b7d886", "text": "Egy 8 cm-es szakasz felezőpontja a végponttól 4 cm-re van.", "type": "true-false", "options": [{"id": "926ed999-d06d-4d8c-b927-004ed2deae51", "text": "Igaz", "isCorrect": true}, {"id": "cb09b20c-ccc3-4494-b79e-fc16c1441942", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b44d1b96-1ddb-4182-973f-4ae33f78c570', '21feff02-016d-46e2-bb9d-c27495133b1b', '53. óra: Szerkesztések', 'Alapszerkesztések: szakasz másolása, szög másolása, merőleges és párhuzamos állítása.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "8ce8053d-b7cc-405f-a0f1-0e3c3d1c8dce", "text": "Milyen eszközt használunk körök és ívek rajzolásához szerkesztéskor?", "type": "multiple-choice", "options": [{"id": "bdec79d4-5135-4968-9f30-f29ea8304da4", "text": "Körzőt", "isCorrect": true}, {"id": "789369b7-bd01-477f-8fee-22534e1c1cc1", "text": "Szögmérőt", "isCorrect": false}, {"id": "2c8b2498-98a4-47fe-b8e5-d8917e08deac", "text": "Radírt", "isCorrect": false}, {"id": "8906d200-b1cd-45d3-ae91-aa1a9e296d8f", "text": "Tollat", "isCorrect": false}], "timeLimit": 15}, {"id": "fbba7e48-b889-401e-ab43-b311b72b15e6", "text": "Milyen vonalzót használunk a tiszta geometrikai szerkesztésekhez?", "type": "multiple-choice", "options": [{"id": "9a6e5c9f-cb48-4902-a711-6fcc6bc4710b", "text": "Beosztás nélküli (egyenes) vonalzót", "isCorrect": true}, {"id": "5f5d2dba-225c-455d-9aa4-cdceafcf7357", "text": "Derékszögű vonalzót beosztással", "isCorrect": false}, {"id": "71a5d5b4-60fc-4f22-add8-b62d7fa4e99a", "text": "Görbe vonalzót", "isCorrect": false}, {"id": "031d9681-39d1-42e4-b6ea-d17032662dc6", "text": "Mérőszalagot", "isCorrect": false}], "timeLimit": 15}, {"id": "3de12104-b374-454a-b20c-5eecbd8d4f86", "text": "Szakasz másolásakor körzővel mérjük fel a szakasz hosszát.", "type": "true-false", "options": [{"id": "3991cb77-e099-441c-891d-e533c45a6ea0", "text": "Igaz", "isCorrect": true}, {"id": "925bc1ae-598b-4b4c-92a9-d3a807bf2a7f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5890157a-3c56-460c-aab6-1850c2f6148f", "text": "A szerkesztéseknél a körzőívek metszéspontjai adják meg a keresett pontokat.", "type": "true-false", "options": [{"id": "7bdc8fde-5ee9-41ae-b621-3401a2f061fe", "text": "Igaz", "isCorrect": true}, {"id": "f599ac38-9197-449c-a668-7355be0a8306", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "97bfd473-0198-47c9-bdf5-679bd68cb513", "text": "Hány fokos szöget zár be két egymásra merőleges egyenes?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "de63239d-685c-41c5-aa7c-77b9d1ef7a67", "text": "Két párhuzamos egyenes sehol sem metszi egymást a síkban.", "type": "true-false", "options": [{"id": "a0ff213c-a55b-4d5c-ab01-030749ae5fda", "text": "Igaz", "isCorrect": true}, {"id": "c00f8f4c-5d9d-412b-b061-62dfaad27f48", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8c547b75-b68f-4f63-9ba9-a10ed803527e", "text": "A pontos és esztétikus szerkesztés alapkövetelmény a geometriában.", "type": "true-false", "options": [{"id": "354faeb7-26b6-454d-b446-5f5ecbd1450b", "text": "Igaz", "isCorrect": true}, {"id": "f61fdefa-62a5-4f73-a8e7-bb72902f1872", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('729cba32-0ba9-44ff-9a6f-453842e104ee', '21feff02-016d-46e2-bb9d-c27495133b1b', '54. óra: Szerkesztések II.', 'Egyszerű szerkesztési feladatok: háromszög szerkesztése oldalaiból (SSSZ), háromszög-egyenlőtlenség.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "09489d6b-a772-45de-849d-dc7653bae868", "text": "Mi a háromszög-egyenlőtlenség szabálya?", "type": "multiple-choice", "options": [{"id": "40cb2172-66b3-4489-9540-591f204d5463", "text": "A háromszög bármely két oldalának összege nagyobb a harmadik oldalnál (a + b > c)", "isCorrect": true}, {"id": "a4cce013-3790-401f-969f-1afd17855b1b", "text": "A három oldal összege 180", "isCorrect": false}, {"id": "d1b0013e-d23c-45c0-8a16-ff58bd3594ab", "text": "A két rövidebb oldal összege kisebb a harmadiknál", "isCorrect": false}, {"id": "3c6b0560-f9b9-4224-b6cf-a4ab8afabd86", "text": "Minden oldal egyenlő", "isCorrect": false}], "timeLimit": 15}, {"id": "09157da0-e8df-41c4-ba59-c127108df268", "text": "Szerkeszthető-e háromszög a 3 cm, 4 cm, 8 cm oldalakkal? (3+4 = 7 < 8)", "type": "true-false", "options": [{"id": "802904f3-f5f1-4ecd-8ffe-ad5719b92504", "text": "Igaz", "isCorrect": false}, {"id": "c23b61ab-f807-4216-80ef-4e0a2a8a5021", "text": "Hamis (nem teljesül a háromszög-egyenlőtlenség)", "isCorrect": true}], "timeLimit": 15}, {"id": "a1aed20f-d3f5-4286-ae3e-97b061f97f06", "text": "Szerkeszthető-e háromszög 5 cm, 6 cm, 7 cm oldalakkal?", "type": "true-false", "options": [{"id": "98a69feb-94ab-4595-9268-5fdba42f95e2", "text": "Igaz (5+6 > 7)", "isCorrect": true}, {"id": "314ce273-c1dd-4c4e-9932-f786ec58d995", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9ccda657-9067-43b3-b093-b20fc0b83d73", "text": "Hány adatra van szükség legalább egy háromszög egyértelmű megszerkesztéséhez?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "4f2cffb2-1bc6-4bb2-8663-4c4cef31861c", "text": "A háromszög szerkesztésének lépései: Vázlat -> Adatok -> Szerkesztés -> Ellenőrzés.", "type": "true-false", "options": [{"id": "eb6e737c-48cf-44c0-a51c-6670f96e1881", "text": "Igaz", "isCorrect": true}, {"id": "ac01e8a6-22a3-4db0-9aef-23f2c1e984e5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "72b30a21-f711-4fc3-9eae-6c3700edb332", "text": "Szerkeszthető-e háromszög 2 cm, 3 cm, 5 cm oldalakkal? (2+3 = 5)", "type": "true-false", "options": [{"id": "adeb9ce6-2e92-4c4f-92d1-3d248a0844c4", "text": "Igaz", "isCorrect": false}, {"id": "4d343cc4-39ca-4563-a63f-3a24d5805c07", "text": "Hamis (kell hogy > legyen, nem =)", "isCorrect": true}], "timeLimit": 15}, {"id": "81eeed0a-ab35-4c24-9ed6-cf621cc23450", "text": "Az egyenlő oldalú háromszög minden oldala egyenlő hosszú.", "type": "true-false", "options": [{"id": "05cef8cb-bdd0-4b77-bbb5-12a61f535d57", "text": "Igaz", "isCorrect": true}, {"id": "ecf3b1d4-51d6-4feb-84e8-e63024e13672", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f1538ad9-a28b-431d-b4de-dbae980cf0fd', '21feff02-016d-46e2-bb9d-c27495133b1b', '55. óra: Számonkérés', 'Számonkérés a síkbeli alakzatokból és alapszerkesztésekből (10 kérdés).', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "73b64589-1a8d-4b82-9a65-8787d15b23b3", "text": "1. Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "55766991-86e5-4eeb-991f-fa52f8217d5e", "text": "2. Mennyi a négyszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "5a4830cb-47b5-4055-8e4d-b9e488663e1f", "text": "3. Szerkeszthető-e háromszög 4 cm, 5 cm, 10 cm oldalakkal?", "type": "true-false", "options": [{"id": "eba0ab27-29ca-43e5-aa61-7156db3ab7e4", "text": "Igaz", "isCorrect": false}, {"id": "90807ad9-e0be-4481-bf38-34dd44ff3183", "text": "Hamis (4+5 < 10)", "isCorrect": true}], "timeLimit": 15}, {"id": "787cc262-9cec-4027-8ec4-e8dda3b68e3c", "text": "4. Ha a kör sugara 7 cm, mennyi az átmérője? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "0c19ec43-eef8-40ce-baca-936e45122d26", "text": "5. Hány fokos szöget zár be a szakaszfelező merőleges a szakasszal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "27efba14-145b-4ae7-abf5-f9da723ddd72", "text": "6. A rombusz minden oldala egyenlő hosszú.", "type": "true-false", "options": [{"id": "1e43e00a-76e2-4d74-a5a3-21561da309ff", "text": "Igaz", "isCorrect": true}, {"id": "07d2fce2-7e0b-4a5f-a09a-8b5cad818c8f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a205e3e8-f845-45c0-9ae0-6c54bac4806b", "text": "7. Milyen szög a 120°-os szög?", "type": "multiple-choice", "options": [{"id": "a07caee3-2887-463c-8bf8-5fde01039e9b", "text": "Tompaszög", "isCorrect": true}, {"id": "3d9f9b65-4ea1-4b08-8ab6-f8675c5c24d3", "text": "Hegyesszög", "isCorrect": false}, {"id": "450b767c-d3f3-44f8-b8b0-c7ada104b05d", "text": "Derékszög", "isCorrect": false}, {"id": "42901430-c0d9-44b1-ae8d-cfd21b772a05", "text": "Egyenesszög", "isCorrect": false}], "timeLimit": 15}, {"id": "00782e19-d719-4cc4-af19-cab0769e6737", "text": "8. Hány átlója van egy négyszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "6356a51a-3016-4f91-8bff-d05df7f5b31c", "text": "9. Az egybevágó alakzatok területe megegyezik.", "type": "true-false", "options": [{"id": "564e6708-0e9a-4308-b1b7-30f23aa16a40", "text": "Igaz", "isCorrect": true}, {"id": "3aa1a76a-6062-46c7-b666-d0e39b0bb9b8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c5b00869-1869-4604-9214-20f26e3f5a62", "text": "10. Hány fokosak a szabályos háromszög szögei?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('53bd8128-d4d0-40ba-a505-4eb16fdeb848', '21feff02-016d-46e2-bb9d-c27495133b1b', '56. óra: Matematikai játékok', 'Geometriai kirakók (Tangram), alakzatok építése, stratégiák.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "d6d10b6b-e139-4d59-87ab-9dfb8414de80", "text": "Hány darabból (tanból) áll a klasszikus Tangram kirakó játék?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "775624f8-b86e-4c4c-831b-e6aad13dd04c", "text": "Milyen síkidomokból áll a Tangram készlet?", "type": "multiple-choice", "options": [{"id": "974ef1c1-053f-4353-8de0-b21fa99e614c", "text": "5 háromszög, 1 négyzet, 1 paralelogramma", "isCorrect": true}, {"id": "3837653b-bd9f-4f02-a7bf-80afafcc9628", "text": "7 négyzet", "isCorrect": false}, {"id": "285f1981-0b4d-4b18-8779-3585c4095f43", "text": "7 kör", "isCorrect": false}, {"id": "6b7c839e-33b3-480e-960f-97a88485a8a4", "text": "3 háromszög, 4 téglalap", "isCorrect": false}], "timeLimit": 15}, {"id": "9c261723-48b1-4747-9caf-1a55db572f68", "text": "A Tangram elemeiből sokféle figura (állatok, emberi alakok, tárgyak) kirakható.", "type": "true-false", "options": [{"id": "7e4ee67b-a955-404c-9970-6db8e3bd2617", "text": "Igaz", "isCorrect": true}, {"id": "4b604708-60f8-4895-97b8-211e9afe3a0a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6636ad69-49ef-43e7-b929-099603dbae39", "text": "A kirakós játékok fejlesztik a térszemléletet és a síkbeli alakzatok felismerését.", "type": "true-false", "options": [{"id": "da7fcbc7-9fd9-4e29-952c-d381a823a34c", "text": "Igaz", "isCorrect": true}, {"id": "ebc6ca74-8168-4226-8a69-29cb9fac785c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "69a2ce6c-7e33-46d9-9d69-f43cf45cfe9a", "text": "A szabályos sokszögekkel hégmentesen lefedhető a sík (pl. szabályos hatoszögekkel).", "type": "true-false", "options": [{"id": "d6065e6b-e7dc-4db7-a74c-2570d023209d", "text": "Igaz", "isCorrect": true}, {"id": "3a59ef7f-e5c9-4c8e-958a-1a811198ff7e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "dba090e1-a656-4a25-b3c5-3940af9d70ac", "text": "Hány oldala van a szabályos hexagonnak (hatszögnek)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "888ee570-219c-4638-88fa-f65d1f817414", "text": "A geometriai játékok során a próbálgatás és a logikai tervezés együtt segít a megoldásban.", "type": "true-false", "options": [{"id": "94290584-5417-494f-bece-ae2b3f042ace", "text": "Igaz", "isCorrect": true}, {"id": "18af157c-1a62-4d82-aa09-6b4ae06e27ae", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('6e79a522-f2ae-4414-bb6e-a8febaf09395', '21feff02-016d-46e2-bb9d-c27495133b1b', '57. óra: Tengelyes tükrözés', 'Tengelyes tükrözés fogalma, tengely (t), tárgy és tükörkép (A és A'').', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "86e9b896-7689-4f7c-acb9-e93d3be4e554", "text": "Mi a tengelyes tükrözés lényege egy ''t'' tengelyre nézve?", "type": "multiple-choice", "options": [{"id": "0717669e-9d6f-42eb-b8d6-1e4c2f7b40ec", "text": "A pont és tükörképe a tengelyre merőleges egyenesen van, és egyenlő távolságra van a tengelytől", "isCorrect": true}, {"id": "8fa292bf-d791-4830-8f4a-5a079d514d54", "text": "A pontot eltoljuk párhuzamosan", "isCorrect": false}, {"id": "1afd9d58-bdfc-492a-9905-3a8c7d9a3004", "text": "A pontot elforgatjuk 180 fokkal", "isCorrect": false}, {"id": "17997e4b-4b18-43ad-8cde-62f97b15e329", "text": "A pontot lefelé mozgatjuk 5 cm-rel", "isCorrect": false}], "timeLimit": 15}, {"id": "afbe6e2e-bb91-42fb-aeb6-180b19a51f35", "text": "Hol van a tengelyen lévő pont tükörképe?", "type": "multiple-choice", "options": [{"id": "b048cb48-53ae-4b80-8ea6-89dd278f5848", "text": "Önmagában (fixpont)", "isCorrect": true}, {"id": "ea32959e-0f8a-43e5-8b19-17aeb51a3806", "text": "Az origóban", "isCorrect": false}, {"id": "d393405c-f6fa-4173-a16e-d7cc591554bf", "text": "Végtelenben", "isCorrect": false}, {"id": "5a34cbe6-43c6-4f52-872e-09cbaf876851", "text": "A tengely másik végén", "isCorrect": false}], "timeLimit": 15}, {"id": "c8ad5e51-3dbb-41ea-a45f-aa97fe60610a", "text": "Ha a P pont 4 cm-re van a tükörtengelytől, milyen messze van a P'' tükörkép a tengelytől?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "c43783aa-7db3-42f8-ab4a-39816b478180", "text": "Milyen messze van a P pont a P'' tükörképétől, ha a tengelytől való távolsága 4 cm?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "f2419212-7289-40fe-80fb-a66a662e06d2", "text": "A tengelyes tükrözés egybevágósági transzformáció.", "type": "true-false", "options": [{"id": "5630634b-c433-4104-810c-d3cecd6d5ea3", "text": "Igaz", "isCorrect": true}, {"id": "3de8d8f0-e84d-478f-be70-9594cbf8e0ee", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "98347096-4357-479e-80ee-ea84c40fabc9", "text": "A tengelyes tükrözés megváltoztatja az alakzat körüljárási irányát (pl. óramutató járásával megegyezőből ellentétes lesz).", "type": "true-false", "options": [{"id": "10b3fe45-5d5c-4c24-a284-19a2e20c2971", "text": "Igaz", "isCorrect": true}, {"id": "5e1e261c-9e66-4184-92c0-aa72d45def6f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "996caea2-f54e-4509-9862-7865f92de520", "text": "A tengelyesen tükrös alakzat és tükörképe egybevágó.", "type": "true-false", "options": [{"id": "a2b13099-3b57-43ed-962e-d69b5f53f3ce", "text": "Igaz", "isCorrect": true}, {"id": "b3365945-9293-4600-85f3-c3b8c7c4981b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('37524481-4b66-4234-b64b-02a50fe63fd2', '21feff02-016d-46e2-bb9d-c27495133b1b', '58. óra: A tengelyes tükrözés tulajdonságai', 'Távolságtartás, szögtartás, körüljárási irány megváltozása, egyenes és kör tükörképe.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "4e98b798-ce8f-4f15-9409-f4f8d8a5eeb9", "text": "Melyik tulajdonság érvényes a tengelyes tükrözésre?", "type": "multiple-choice", "options": [{"id": "63bdac63-485f-49db-a4a3-80af22da354a", "text": "Távolságtartó, szögtartó, egyenestartó és megváltoztatja a körüljárási irányt", "isCorrect": true}, {"id": "2b406b7e-e558-456b-89e8-d12a0f13b717", "text": "Növeli a szakaszok hosszát", "isCorrect": false}, {"id": "e9cc8154-ffc9-4c17-af61-1c8405ef9751", "text": "Megváltoztatja a szögek nagyságát", "isCorrect": false}, {"id": "e6b9970b-fc40-41a7-9ad1-221778c9a1de", "text": "Négyszögből háromszöget csinál", "isCorrect": false}], "timeLimit": 15}, {"id": "67a108e2-0968-4f9c-a213-12318efc837f", "text": "Egy 5 cm-es szakasz tengelyes tükörképe is 5 cm hosszú.", "type": "true-false", "options": [{"id": "afda6904-4825-4ff5-abcd-90240f6c7596", "text": "Igaz (távolságtartó)", "isCorrect": true}, {"id": "a4bbe33f-badf-473c-8878-a56dd22205b9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "93ffd606-969e-4a02-a1aa-45449fe42e72", "text": "Egy 45°-os szög tengelyes tükörképe is 45°-os.", "type": "true-false", "options": [{"id": "f4df09ae-04c9-4475-a75b-712807acc42e", "text": "Igaz (szögtartó)", "isCorrect": true}, {"id": "43591c66-bece-4cc6-acad-0eac17bcca37", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "264690ac-8773-4501-af1e-df47e4aa0a60", "text": "A tengelyre merőleges egyenes tükörképe önmaga (önmagába transzformálódik).", "type": "true-false", "options": [{"id": "00bbce74-90aa-4f40-8bce-8e13af63baf9", "text": "Igaz", "isCorrect": true}, {"id": "fc286c03-a621-47fa-bc61-b3804f83ec1b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0eada76b-f514-45f7-9dc3-aff6a384f0cd", "text": "Egy kör tengelyes tükörképe ugyanolyan sugarú kör.", "type": "true-false", "options": [{"id": "4cbdca2f-b8d5-4880-9fc5-79c07eefe6d3", "text": "Igaz", "isCorrect": true}, {"id": "d8a50e40-9eca-41a1-a2f1-a9065f792d34", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8fc940ea-107e-486e-96e0-59929c49b69f", "text": "A tengellyel párhuzamos egyenes tükörképe is párhuzamos a tengellyel.", "type": "true-false", "options": [{"id": "27160505-144e-4d66-9194-7909a2bafb4c", "text": "Igaz", "isCorrect": true}, {"id": "8b4c4c04-bc6a-439b-9986-8f3c8b4c7444", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "433ac63b-f8b8-431f-8ccf-fbc4bd0f5ea1", "text": "Hány fixpontja (helyben maradó pontja) van a tengelyes tükrözésnek a síkban?", "type": "multiple-choice", "options": [{"id": "2e842541-a220-4d27-b96d-59ee96c654b3", "text": "Végtelen sok (a tükörtengely minden pontja)", "isCorrect": true}, {"id": "77f6cf66-fa1c-4050-bbb8-47232314def8", "text": "Csak 1", "isCorrect": false}, {"id": "4b8ab2f4-647a-4eeb-bc80-7fbe0f2c780c", "text": "Nincs egy sem", "isCorrect": false}, {"id": "373dacfd-9aef-49f4-a5ae-acec045c0cc1", "text": "Pontosan 2", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('755ad370-c6a7-4586-9c2d-90b8ac570c89', '21feff02-016d-46e2-bb9d-c27495133b1b', '59. óra: Gyakorlóóra', 'Tengelyes tükörkép szerkesztésének gyakorlása pontok, szakaszok, sokszögek esetén.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "d8e65bd1-704b-460a-abfe-499e4ab94410", "text": "Hogyan szerkesztjük meg egy P pont ''t'' tengelyre vonatkozó tükörképét?", "type": "multiple-choice", "options": [{"id": "c988d49a-5158-4ff5-8beb-b62f6b99b992", "text": "Merőlegest állítunk P-ből ''t''-re, és a talpponttól felmérjük a P távolságát a merőlegesre", "isCorrect": true}, {"id": "c59e1416-fbbb-4275-94d3-cd1b33deac11", "text": "Párhuzamost húzunk ''t''-vel", "isCorrect": false}, {"id": "ab740ade-95d1-4077-8ef4-f2ec8b916592", "text": "Körzővel kört rajzolunk P középponttal", "isCorrect": false}, {"id": "d2356025-0f03-4a12-b524-48c299d0a9a3", "text": "Összekötjük P-t az origóval", "isCorrect": false}], "timeLimit": 15}, {"id": "fbf9a62f-41b7-4925-bdd8-b6cb40fcf8e9", "text": "Egy háromszög tengelyes tükrözése után a kapott háromszög területe megegyezik az eredetivel.", "type": "true-false", "options": [{"id": "d240bcb7-2d09-4177-9769-c7de1cd8ba3e", "text": "Igaz", "isCorrect": true}, {"id": "8912fba4-4892-4721-85f1-7d66ac28672a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "43aaa0a5-25a6-4b91-9d35-9a3d4870727e", "text": "Ha a P pont a tengelyen van, hol van a tükörképe?", "type": "multiple-choice", "options": [{"id": "244059b7-5cea-42f5-98ec-daa2d6e6e441", "text": "Önmagában (P = P'')", "isCorrect": true}, {"id": "29a360ac-ae88-4f32-8493-212dc37dd721", "text": "A tengely másik oldalán", "isCorrect": false}, {"id": "ee14f704-297c-4836-b81a-af950daeeb63", "text": "A sík szélén", "isCorrect": false}, {"id": "1c343fda-acf9-4020-abfc-3874c20456fe", "text": "Az origóban", "isCorrect": false}], "timeLimit": 15}, {"id": "4cbd66ef-fc2a-4ec3-b6fe-400c42386e08", "text": "A szakasz felezőmerőlegese a szakaszt önmagára tükrözi vissza.", "type": "true-false", "options": [{"id": "b4d02103-2013-4034-8b5e-a0e354274edf", "text": "Igaz", "isCorrect": true}, {"id": "9a39a467-bb1e-4a2e-972a-f12868bf55e4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4a6c2b8b-c4da-40e0-b042-7f7b16088b97", "text": "Melyik betűnek VAN függőleges szimmetriatengelye? (pl. A, M, Y, W)", "type": "multiple-choice", "options": [{"id": "697841d0-b49d-4bd9-a63b-b69c245bb4c1", "text": "A", "isCorrect": true}, {"id": "502eb432-bd49-4a14-a645-0a7c8cf6bd18", "text": "F", "isCorrect": false}, {"id": "c571d47c-e31b-41a0-bfdb-e88c12004455", "text": "L", "isCorrect": false}, {"id": "5b581de6-d9ff-4f3b-8342-12bb974c470a", "text": "R", "isCorrect": false}], "timeLimit": 15}, {"id": "112a0260-3564-422d-841b-5f7cc695fee1", "text": "Melyik betűnek VAN vízszintes szimmetriatengelye? (pl. B, C, D, E, K)", "type": "multiple-choice", "options": [{"id": "dacad564-7a2d-4365-af17-68eddde623d2", "text": "E", "isCorrect": true}, {"id": "d4c4d372-e8bd-4fbd-9fcc-03841eb3114b", "text": "F", "isCorrect": false}, {"id": "10c9a8e8-444b-4161-b27e-e69a7166d08e", "text": "G", "isCorrect": false}, {"id": "9db3a8bd-430b-45b7-9a91-41b13f4f160d", "text": "J", "isCorrect": false}], "timeLimit": 15}, {"id": "3219c9b1-9058-4eb1-9881-fdd9b2fdf158", "text": "A tengelyesen tükrös alakzatok szimmetrikusak a tükörtengelyre.", "type": "true-false", "options": [{"id": "b4f1afcc-9828-461f-966f-1e2ab5264aca", "text": "Igaz", "isCorrect": true}, {"id": "ede65b0c-2e84-4193-9528-6c1af3026b12", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('8b565153-abb1-43e1-9fb0-e9e3e25d50e6', '21feff02-016d-46e2-bb9d-c27495133b1b', '60. óra: Tengelyes szimmetria', 'Tengelyesen szimmetrikus alakzatok, szögfelező és felezőmerőleges szimmetriatengelyként.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "774c60d3-45d6-4c59-84df-8029e2bc93b2", "text": "Mikor nevezünk egy síkidomot tengelyesen szimmetrikusnak?", "type": "multiple-choice", "options": [{"id": "01638e54-a5b3-4118-bf34-714ee77cb8c5", "text": "Ha van legalább egy olyan egyenes (szimmetriatengely), amelyre tükrözve a síkidom önmagába megy át", "isCorrect": true}, {"id": "36c49252-45b6-47a4-a581-24e0fed8a8b6", "text": "Ha minden oldala egyenlő", "isCorrect": false}, {"id": "a246054d-bb81-42fb-856c-84b82d05c369", "text": "Ha kerek", "isCorrect": false}, {"id": "15445840-e91d-422e-ae46-fee0b5f2d958", "text": "Ha nincs szöge", "isCorrect": false}], "timeLimit": 15}, {"id": "57096231-646f-46cd-84db-be3b864438fc", "text": "Mi a szögfelező egyenes fő tulajdonsága?", "type": "multiple-choice", "options": [{"id": "a507832a-0939-4d04-bbfc-34e33a2be97b", "text": "A szögtartományt két egyenlő szögre osztja, és pontjai egyenlő távolságra vannak a szög száraitól", "isCorrect": true}, {"id": "c962ca4c-7f76-4f50-9a15-69a2555849d2", "text": "A szög szárait meghosszabbítja", "isCorrect": false}, {"id": "3b97acec-eee8-4e9e-acb9-7546503b05a3", "text": "Merőleges a szög száira", "isCorrect": false}, {"id": "81026643-6bde-407e-b425-d4a82b25afc0", "text": "Párhuzamos a szög száival", "isCorrect": false}], "timeLimit": 15}, {"id": "7ba8e32e-a129-4a5b-a300-82011342fce7", "text": "A szögfelező egyenes a szög szimmetriatengelye.", "type": "true-false", "options": [{"id": "fec6be85-ca36-4e52-944f-a4eedfc8712e", "text": "Igaz", "isCorrect": true}, {"id": "065c5ce3-c3dd-4edd-a1fa-359adf0c9b30", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "82e8f2d5-426e-4fdf-b3cf-a794b181f7ea", "text": "Hány szimmetriatengelye van egy 60°-os szögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "2d00fa85-7c59-44b0-8f0d-2cc68846334d", "text": "Hány szimmetriatengelye van a körnek?", "type": "multiple-choice", "options": [{"id": "c1e4a926-7926-4780-a1d5-0e228ae6b82d", "text": "Végtelen sok (minden középponton átmenő egyenes)", "isCorrect": true}, {"id": "dd914b7c-f396-4094-9881-18bb52562dcf", "text": "1", "isCorrect": false}, {"id": "c8a00d71-8c5d-4859-9334-72b1697d1f2b", "text": "2", "isCorrect": false}, {"id": "1f364a96-fc78-414e-8680-96d8decab6cc", "text": "4", "isCorrect": false}], "timeLimit": 15}, {"id": "ac6d1a56-ce63-478c-83f8-798f183ee05a", "text": "A szögfelező megszerkesztéséhez körzőíveket használunk a szög szárain.", "type": "true-false", "options": [{"id": "0b5830f4-40a4-4050-9b4b-b26dbbc961ee", "text": "Igaz", "isCorrect": true}, {"id": "1cb5de4f-29b8-41d0-81d0-a5fc2f77d0e2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "da633539-213c-4488-a38a-da5d33a091b6", "text": "Hány fokos két 30°-os részre osztja a szögfelező a 60°-os szöget?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;